#!/usr/bin/env python3
"""todoline-cli CLI - generated by clivane openapi (deterministic, stdlib only).

One subcommand per operationId. Set the base URL with --base-url or the
TODOLINE_BASE_URL environment variable. Responses print raw; --json wraps them in an
envelope {"status": int, "body": <parsed-or-text>}.
"""
import argparse
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

OPS = json.loads(r"""[
 {
  "cmd": "create-todo",
  "doc": "Create a todo (JSON body via --body)",
  "has_body": true,
  "method": "POST",
  "operationId": "createTodo",
  "params": [],
  "path": "/todos"
 },
 {
  "cmd": "delete-todo",
  "doc": "Delete one todo by id",
  "has_body": false,
  "method": "DELETE",
  "operationId": "deleteTodo",
  "params": [
   {
    "flag": "--todo-id",
    "in": "path",
    "name": "todoId",
    "required": true,
    "type": "integer"
   }
  ],
  "path": "/todos/{todoId}"
 },
 {
  "cmd": "get-todo",
  "doc": "Fetch one todo by id",
  "has_body": false,
  "method": "GET",
  "operationId": "getTodo",
  "params": [
   {
    "flag": "--todo-id",
    "in": "path",
    "name": "todoId",
    "required": true,
    "type": "integer"
   }
  ],
  "path": "/todos/{todoId}"
 },
 {
  "cmd": "list-todos",
  "doc": "List todos, optionally filtered by completion state",
  "has_body": false,
  "method": "GET",
  "operationId": "listTodos",
  "params": [
   {
    "flag": "--done",
    "in": "query",
    "name": "done",
    "required": false,
    "type": "string"
   }
  ],
  "path": "/todos"
 }
]""")
DEFAULT_BASE = "http://localhost:8799"


def build_parser():
    parser = argparse.ArgumentParser(prog="todoline-cli", description="API CLI: Todoline API")
    parser.add_argument("--base-url", default=os.environ.get("TODOLINE_BASE_URL", DEFAULT_BASE))
    sub = parser.add_subparsers(dest="command")
    for op in OPS:
        p = sub.add_parser(op["cmd"], help=op["doc"])
        for prm in op["params"]:
            p.add_argument(prm["flag"], required=prm["required"],
                           help="%s (%s)" % (prm["in"], prm["type"]))
        if op["has_body"]:
            p.add_argument("--body", default=None, help="JSON request body")
        p.add_argument("--json", action="store_true", help="structured envelope")
    return parser


def main(argv=None):
    parser = build_parser()
    ns = parser.parse_args(argv)
    if not ns.command:
        parser.print_help()
        return 2
    op = next(o for o in OPS if o["cmd"] == ns.command)
    path = op["path"]
    query = {}
    for prm in op["params"]:
        value = getattr(ns, prm["name"])
        if value is None:
            continue
        if prm["in"] == "path":
            path = path.replace("{" + prm["name"] + "}", urllib.parse.quote(str(value)))
        elif prm["in"] == "query":
            query[prm["name"]] = value
    url = ns.base_url.rstrip("/") + path
    if query:
        url += "?" + urllib.parse.urlencode(query)
    data = None
    headers = {"Accept": "application/json"}
    if op["has_body"] and getattr(ns, "body", None):
        data = ns.body.encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method=op["method"])
    try:
        with urllib.request.urlopen(req) as resp:
            status, raw = resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        status, raw = exc.code, exc.read().decode("utf-8", "replace")
    try:
        body = json.loads(raw)
    except Exception:
        body = raw
    if ns.json:
        print(json.dumps({"status": status, "body": body}, indent=2, sort_keys=True))
    elif isinstance(body, (dict, list)):
        print(json.dumps(body, indent=2, sort_keys=True))
    else:
        print(body)
    return 0 if status < 400 else 1


if __name__ == "__main__":
    sys.exit(main())
